import sys
from collections import deque

RANK = {r: i for i, r in enumerate('A23456789TJQK', 1)}
def fits(card, top):
    return RANK[card[0]] + 1 == RANK[top[0]] and ((card[1] in 'DH') != (top[1] in 'DH'))
def play(hand, piles):
    moved = False
    while hand:
        for i, card in enumerate(hand):
            if card[0] == 'K':
                destination = next((p for p in (1, 3, 5, 7) if not piles[p]), None)
            else:
                destination = next((p for p in range(8) if piles[p] and fits(card, piles[p][-1])), None)
            if destination is not None:
                piles[destination].append(hand.pop(i))
                moved = True
                break
        else:
            break
    return moved
deck = sys.stdin.read().split()
hands = [deck[:14:2], deck[1:14:2]]
piles = [[] for _ in range(8)]
for p, card in zip((0, 2, 4, 6), deck[14:18]):
    piles[p].append(card)
draw = deque(deck[18:])
player = 0
while True:
    hand = hands[player]
    moved_pile = False
    # Source priority precedes target priority, and at most one pile moves.
    for source in range(8):
        if not piles[source]:
            continue
        for target in range(8):
            if target != source and piles[target] and fits(piles[source][0], piles[target][-1]):
                piles[target].extend(piles[source])
                # min keeps the leftmost of equal minimum ranks.
                lowest = min(range(len(hand)), key=lambda i: RANK[hand[i][0]])
                piles[source] = [hand.pop(lowest)]
                moved_pile = True
                break
        if moved_pile:
            break
    played = play(hand, piles)
    if not hand:
        break
    if not moved_pile and not played and draw:
        hand.append(draw.popleft())
    player ^= 1
print(player + 1, *(pile[-1] if pile else 'E' for pile in piles))
